 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            rs = [x for x, _ in cells]
            cs = [y for _, y in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            out.append({"color": color, "cells": cells, "r0": r0, "r1": r1,
                        "c0": c0, "c1": c1, "area": len(cells),
                        "box": (r1 - r0 + 1) * (c1 - c0 + 1)})
    return out


def transform(grid):
    """Recolor the object opposite the thin, edge-anchored colored path."""
    h, w = len(grid), len(grid[0])
    objs = _components(grid)

    # The marker is a sparse component anchored on a border (usually an L path).
    markers = []
    for o in objs:
        touches = sum((o["r0"] == 0, o["r1"] == h - 1,
                       o["c0"] == 0, o["c1"] == w - 1))
        if o["area"] >= 5 and touches and o["area"] / o["box"] <= 0.60:
            markers.append((touches, o["area"] / o["box"], o["area"], o))
    if not markers:
        return [row[:] for row in grid]
    marker = min(markers, key=lambda x: (x[1], -x[0], x[2]))[3]

    # Find the sizable interior component in the marker's row band, on the
    # opposite horizontal side. Edge-touching decorations are not candidates.
    marker_left = (marker["c0"] + marker["c1"]) / 2 < w / 2
    candidates = []
    for o in objs:
        if o is marker or o["area"] < 3:
            continue
        if o["r1"] < marker["r0"] or o["r0"] > marker["r1"]:
            continue
        if o["r0"] == 0 or o["r1"] == h - 1 or o["c0"] == 0 or o["c1"] == w - 1:
            continue
        center_c = (o["c0"] + o["c1"]) / 2
        if marker_left and center_c <= marker["c1"]:
            continue
        if not marker_left and center_c >= marker["c0"]:
            continue
        overlap = max(0, min(o["r1"], marker["r1"]) - max(o["r0"], marker["r0"]) + 1)
        candidates.append((o["area"], overlap, -abs(center_c - (marker["c0"] + marker["c1"]) / 2), o))
    if not candidates:
        return [row[:] for row in grid]
    target = max(candidates, key=lambda x: (x[0], x[1], x[2]))[3]
    result = [row[:] for row in grid]
    for r, c in target["cells"]:
        result[r][c] = marker["color"]
    return result
