 "content": "from collections import Counter, deque


def components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == color:
                        seen.add((a,b)); q.append((a,b))
            rs=[r for r,c in cells]; cs=[c for r,c in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            result.append(dict(color=color,cells=cells,area=len(cells),r0=r0,r1=r1,c0=c0,c1=c1,
                               height=r1-r0+1,width=c1-c0+1))
    return result


def transform(grid):
    """Extend the inward ray of an edge L marker; recolor the first object hit."""
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs=components(grid,bg)
    candidates=[]
    for o in objs:
        touches=(o['r0']==0 or o['r1']==h-1 or o['c0']==0 or o['c1']==w-1)
        density=o['area']/(o['height']*o['width'])
        if touches and o['height']>=3 and o['width']>=3 and density<=0.65:
            candidates.append(o)
    if not candidates:
        return [row[:] for row in grid]
    marker=max(candidates,key=lambda o:o['area'])
    cells=set(marker['cells'])
    # Find an elbow cell that has both a horizontal and vertical arm.
    elbows=[]
    for r,c in cells:
        horiz=((r,c-1) in cells or (r,c+1) in cells)
        vert=((r-1,c) in cells or (r+1,c) in cells)
        if horiz and vert: elbows.append((r,c))
    if not elbows:
        return [row[:] for row in grid]
    # The L is edge-anchored. Its inward continuation follows the vertical
    # arm away from the horizontal edge-facing segment.
    r0,r1,c0,c1=marker['r0'],marker['r1'],marker['c0'],marker['c1']
    corner=min(elbows,key=lambda p: (abs(p[0]-r0)+abs(p[1]-c0)))
    r,c=corner
    vertical_neighbors=[rr for rr in (r-1,r+1) if (rr,c) in cells]
    if not vertical_neighbors:
        return [row[:] for row in grid]
    vr=vertical_neighbors[0]
    dr=1 if vr<r else -1  # point opposite the marker's vertical run
    out=[row[:] for row in grid]
    occupied={ (rr,cc):o for o in objs for rr,cc in o['cells'] }
    rr=r+dr
    while 0<=rr<h:
        hit=occupied.get((rr,c))
        if hit is not None and hit is not marker:
            for ar,ac in hit['cells']:
                out[ar][ac]=marker['color']
            return out
        rr+=dr
    return out
