            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for c in range(w):
            rr = [r for r, cc in cells if cc == c]
            if len(rr) >= 4 and max(rr) - min(rr) + 1 == len(rr) and (min(rr) == 0 or max(rr) == h-1):
                candidates.append((len(rr), color, 'v', c, min(rr), max(rr)))
        for r in range(h):
            cc = [c for rr, c in cells if rr == r]
            if len(cc) >= 3 and max(cc) - min(cc) + 1 == len(cc) and (min(cc) == 0 or max(cc) == w-1):
                candidates.append((len(cc), color, 'h', r, min(cc), max(cc)))
    if not candidates:
        return [row[:] for row in grid]
    length, color, orient, fixed, start, end = max(candidates)
    # For a vertical border stroke, inspect the neighboring interior strip for
    # the small colored object aligned to its row span (the indicated motif).
    targets = []
    if orient == 'v':
        for r in range(max(0, start), min(h, end + 1)):
            for c in range(w):
                if grid[r][c] in (bg, color):
                    continue
                # score components by distance to stroke and keep compact motifs
                comp = grid[r][c]
                cells = [(rr, cc) for rr in range(h) for cc in range(w) if grid[rr][cc] == comp]
                # the target color appears immediately inward from the stroke
                dist = abs(c - fixed)
