def transform(grid):
    """Continue the edge-color line through the shape family indicated by its run."""
    h,w=len(grid),len(grid[0]); counts=Counter(x for row in grid for x in row)
    bg=counts.most_common(1)[0][0]; possibilities=[]
    for col in counts:
        if col==bg:continue
        # Long vertical runs touching a border are guide strokes.
        for c in range(w):
            rows=[r for r in range(h) if grid[r][c]==col]
            for run in _runs(rows):
                if len(run)>=3 and (run[0]==0 or run[-1]==h-1):
                    possibilities.append((len(run),col,'v',c,run[0],run[-1]))
        # Long horizontal runs touching a border.
        for r in range(h):
            cols=[c for c in range(w) if grid[r][c]==col]
            for run in _runs(cols):
                if len(run)>=3 and (run[0]==0 or run[-1]==w-1):
                    possibilities.append((len(run),col,'h',r,run[0],run[-1]))
    if not possibilities:return [row[:] for row in grid]
    length,col,axis,fixed,start,end=max(possibilities)
    # Move parallel to the long arm, away from the border. Stop at the first
    # other color, which is the matching motif to recolor.
    if axis=='v':
        direction=1 if start==0 else -1
        line=[(r,fixed) for r in range(start+direction,end+direction,direction)]
    else:
        direction=1 if start==0 else -1
        line=[(fixed,c) for c in range(start+direction,end+direction,direction)]
    # A guide points perpendicular to its border run; test the cells just inside
    # its occupied span, at the closest offset from the line.
    tests=[]
    if axis=='v':
        for r in range(start,end+1):
            for dc in (-1,1):
                c=fixed+dc
                if 0<=c<w:tests.append((abs(dc),r,c))
    else:
        for c in range(start,end+1):
            for dr in (-1,1):
                r=fixed+dr
                if 0<=r<h:tests.append((abs(dr),r,c))
    found=[]
    for _,r,c in tests:
        v=grid[r][c]
        if v!=bg and v!=col:found.append((v,r,c))
    if not found:return [row[:] for row in grid]
    old,r,c=found[0]
    # Recolor full connected same-color component.
    seen={(r,c)};stack=[(r,c)]
    while stack:
        x,y=stack.pop()
        for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==old:
                seen.add((a,b));stack.append((a,b))
